import { randomUUID } from "node:crypto";
import { homedir } from "node:os";
import { PiService, assistantText } from "./pi.ts";
import { HomeRouter, type Route } from "./home-routing.ts";
import { State, now, type HomeMessage, type SessionRecord, type Turn } from "./state.ts";
import type { AgentSession } from "@earendil-works/pi-coding-agent";

type Active = { session: AgentSession; turn: Turn; output: string; error: string; stopped: boolean;
  commentary: string; tool: string; thinking: string; lastProgress: string; savedProgress: string };
const clean = (text: string) => text.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, "").replace(/[\x00-\x08\x0b-\x1f\x7f]/g, "");
const errorText = (error: unknown) => error instanceof Error ? error.message : String(error);
const toolLabels: Record<string, string> = {
  read: "Looking through files", grep: "Looking through files", find: "Looking through files", ls: "Looking through files",
  edit: "Editing files", write: "Editing files", bash: "Running a command", computer_use: "Using your computer",
};
function toolLabel(name: string, args: unknown) {
  if (name === "delegate") return (args as { role?: string })?.role === "reviewer" ? "Reviewing" : "Researching";
  return toolLabels[name] || `Tool: ${name}`;
}
function replyPrompt(text: string, reply?: { role: string; text: string }) {
  return reply ? `In reply to this earlier ${reply.role} message:\n> ${reply.text.slice(0, 2000).replaceAll("\n", "\n> ")}\n\n${text}` : text;
}

export class Assistant {
  readonly dataDir: string;
  readonly cwd: string;
  readonly concurrency = 4;
  readonly state: State;
  readonly pi: PiService;
  readonly router: HomeRouter;
  private listeners = new Set<(event: unknown) => void>();
  private active = new Map<string, Active>();
  private starting = new Set<string>();
  private pendingStops = new Set<string>();
  private homeRouting: Promise<void> = Promise.resolve();
  private closing = false;
  constructor(dataDir: string, cwd: string) {
    this.dataDir = dataDir;
    this.cwd = cwd;
    this.state = new State(dataDir, () => { if (this.state) this.emit({ type: "snapshot", data: this.snapshot() }); });
    this.pi = new PiService(dataDir, this.state.db);
    this.router = new HomeRouter(this.state, this.pi, cwd);
    queueMicrotask(() => this.drain());
  }
  subscribe(listener: (event: unknown) => void) { this.listeners.add(listener); return () => this.listeners.delete(listener); }
  private emit(event: unknown) { for (const listener of this.listeners) listener(event); }
  snapshot() { return this.state.data; }
  activities() { return [...this.active.values()].filter((run) => run.turn.sourceId)
    .map((run) => ({ type: "homeActivity", sourceId: run.turn.sourceId, text: run.lastProgress })); }
  submitHome(text: string, id?: string) {
    const message = this.state.message(text, id);
    const routed = this.homeRouting.then(async () => {
      try {
        const route = await this.router.discover(message);
        await this.commitRoute(message, route);
      }
      catch (error) { message.status = "failed"; this.state.entry(message, "Routing failed", null); const entry = this.state.data.entries.at(-1)!; this.state.update(entry, errorText(error), "error", "failed"); this.state.save(); }
    });
    this.homeRouting = routed.catch(() => undefined);
    return message;
  }
  private async commitRoute(message: HomeMessage, route: Route) {
    let session: SessionRecord;
    if (route.mode === "start") {
      const cwd = route.cwd?.trim() || homedir();
      const pi = await this.pi.create(cwd, randomUUID());
      session = { id: pi.sessionId, title: clean(route.title.slice(0, 100)), cwd, file: pi.sessionFile!, status: "idle", createdAt: now() };
      this.pi.dispose(pi);
      this.state.data.sessions.push(session);
    } else session = this.state.data.sessions.find((item) => item.id === route.sessionId)!;
    const entry = this.state.entry(message, session.title, session.id);
    this.state.data.turns.push({ id: randomUUID(), sessionId: session.id, entryId: entry.id, sourceId: message.id,
      text: message.text, status: "queued", createdAt: now() });
    message.status = "routed";
    this.state.save();
    this.drain();
  }
  private replyTarget(id: string, sessionId?: string) {
    const message = this.state.data.messages.find((item) => item.id === id);
    if (message) {
      const entry = this.state.data.entries.find((item) => item.id === message.entryId);
      return entry && { entry, sessionId: entry.sessionId, text: message.text, role: "user" };
    }
    for (const entry of this.state.data.entries) {
      const update = entry.updates.find((item) => item.id === id);
      if (update) return { entry, sessionId: entry.sessionId, text: update.text, role: "assistant" };
    }
    const record = this.state.data.sessions.find((session) => session.id === sessionId);
    const reply = record && this.pi.transcript(record.file).find((message) => message.id === id && message.replyable);
    if (reply) return { entry: undefined, sessionId, text: reply.text, role: "assistant" };
  }
  submitSession(sessionId: string, text: string, mode: "followUp" | "steer" = "followUp", options: { replyToId?: string; editOfId?: string; id?: string; reaction?: "thumbs-up" } = {}) {
    const { replyToId, editOfId, id, reaction } = options;
    const record = this.state.data.sessions.find((session) => session.id === sessionId);
    if (!record) throw new Error("Conversation not found");
    if (replyToId && editOfId) throw new Error("Choose Reply or Edit");
    const referenced = replyToId || editOfId ? this.replyTarget((replyToId || editOfId)!, sessionId) : undefined;
    if (replyToId && referenced?.sessionId !== sessionId) throw new Error("Reply target is not in this conversation");
    if (reaction) {
      if (mode !== "followUp" || !replyToId || referenced?.role !== "assistant") throw new Error("React to an assistant reply");
      if (this.state.data.messages.some((message) => message.reaction === reaction && message.replyToId === replyToId)) return { reacted: true };
      text = "Yes, go ahead.";
    }
    const active = this.active.get(sessionId);
    if (editOfId && (mode !== "steer" || referenced?.role !== "user" || referenced.sessionId !== sessionId || active?.turn.sourceId !== editOfId))
      throw new Error("This message is no longer active. Use Reply for a follow-up.");
    if (editOfId && text === referenced?.text) throw new Error("Change the message before sending a revision");
    let entry = mode === "steer" && active
      ? this.state.data.entries.find((item) => item.id === active.turn.entryId)
      : referenced?.entry || [...this.state.data.entries].reverse().find((item) => item.sessionId === sessionId);
    const source = this.state.message(text, id, editOfId ? { editOfId } : { replyToId, ...(reaction && { reaction }) });
    source.status = "routed";
    entry ||= this.state.entry(source, record.title, sessionId);
    source.entryId = entry.id;
    if (mode === "steer" && active) {
      active.turn.sourceId = source.id;
      if (editOfId) active.turn.text = text;
      if (entry) entry.status = "working";
      this.state.save();
      void active.session.steer(editOfId ? `Use this revision of my active request:\n${text}` : replyPrompt(text, referenced))
        .catch((error) => { if (entry) this.state.update(entry, errorText(error), "error", "failed", source.id); });
      return { steered: true };
    }
    const turn: Turn = { id: randomUUID(), sessionId, entryId: entry?.id || null, sourceId: source.id, replyToId, text, status: "queued", createdAt: now() };
    this.state.data.turns.push(turn);
    this.state.save();
    this.drain();
    return { turn };
  }
  dequeue(sessionId: string, turnId: string) {
    const turn = this.state.data.turns.find((item) => item.id === turnId && item.sessionId === sessionId);
    if (!turn || turn.status !== "queued") throw new Error("This message has already started or is no longer queued.");
    const message = this.state.data.messages.find((item) => item.id === turn.sourceId);
    const entry = this.state.data.entries.find((item) => item.id === turn.entryId);
    // A resumed request already has history; withdrawing its retry keeps that history.
    const hasHistory = entry?.updates.some((update) => (update.sourceId || entry.sourceId) === message?.id);
    const removedMessageId = message && !hasHistory ? message.id : undefined;
    this.state.data.turns = this.state.data.turns.filter((item) => item.id !== turn.id);
    if (removedMessageId) {
      this.state.data.messages = this.state.data.messages.filter((item) => item.id !== removedMessageId);
      for (const item of this.state.data.messages) if (item.replyToId === removedMessageId) item.replyToId = undefined;
      for (const item of this.state.data.turns) if (item.replyToId === removedMessageId) item.replyToId = undefined;
      if (entry) {
        const remaining = this.state.data.messages.filter((item) => item.entryId === entry.id);
        if (!remaining.length && !entry.updates.length) this.state.data.entries = this.state.data.entries.filter((item) => item.id !== entry.id);
        else if (entry.sourceId === removedMessageId && remaining[0]) entry.sourceId = remaining[0].id;
      }
    }
    this.state.save();
    return { turn, message, removedMessageId };
  }
  async steerQueued(sessionId: string, turnId: string) {
    const turn = this.state.data.turns.find((item) => item.id === turnId && item.sessionId === sessionId);
    if (!turn || turn.status !== "queued") throw new Error("This message has already started or is no longer queued.");
    const active = this.active.get(sessionId);
    if (!active || active.stopped) throw new Error("There is no active work to steer. The message is still queued.");
    const source = this.state.data.messages.find((item) => item.id === turn.sourceId);
    const entry = this.state.data.entries.find((item) => item.id === active.turn.entryId);
    const previousEntryId = source?.entryId;
    const previousSourceId = active.turn.sourceId;
    const previousStatus = entry?.status;
    const index = this.state.data.turns.indexOf(turn);
    const reply = turn.replyToId && this.replyTarget(turn.replyToId, sessionId);
    // Claim the queued item before awaiting Pi, so it cannot also start as a follow-up.
    this.state.data.turns.splice(index, 1);
    active.turn.sourceId = turn.sourceId;
    if (source) source.entryId = active.turn.entryId;
    if (entry) entry.status = "working";
    this.state.save();
    try {
      await active.session.steer(replyPrompt(turn.text, reply || undefined));
    } catch (error) {
      if (source) source.entryId = previousEntryId ?? null;
      if (active.turn.sourceId === turn.sourceId) active.turn.sourceId = previousSourceId;
      if (entry && entry.status === "working" && previousStatus) entry.status = previousStatus;
      this.state.data.turns.splice(Math.min(index, this.state.data.turns.length), 0, turn);
      this.state.save();
      this.drain();
      throw error;
    }
    if (previousEntryId && previousEntryId !== active.turn.entryId) {
      const old = this.state.data.entries.find((item) => item.id === previousEntryId);
      const remaining = this.state.data.messages.filter((item) => item.entryId === previousEntryId);
      if (old && !old.updates.length && !remaining.length) this.state.data.entries = this.state.data.entries.filter((item) => item.id !== old.id);
      else if (old?.sourceId === source?.id && remaining[0]) old.sourceId = remaining[0].id;
    }
    this.state.save();
    return { turn, steered: true };
  }
  stop(sessionId: string) {
    const active = this.active.get(sessionId);
    if (!active) {
      if (!this.starting.has(sessionId)) return false;
      this.pendingStops.add(sessionId);
      return true;
    }
    active.stopped = true;
    void active.session.abort();
    return true;
  }
  async shutdown() {
    this.closing = true;
    const interrupted = this.state.data.turns.filter((item) => item.status === "running");
    await Promise.allSettled([...this.active.values()].map((run) => run.session.abort()));
    for (const turn of interrupted) {
      const entry = this.state.data.entries.find((item) => item.id === turn.entryId);
      if (entry) { entry.status = "interrupted"; entry.interruptedText = turn.text; entry.interruptedSourceId = turn.sourceId; }
      const record = this.state.data.sessions.find((item) => item.id === turn.sessionId);
      if (record) record.status = "interrupted";
    }
    this.state.data.turns = this.state.data.turns.filter((item) => item.status !== "running");
    this.state.save();
  }
  resume(entryId: string) {
    const entry = this.state.data.entries.find((item) => item.id === entryId);
    if (!entry?.sessionId || entry.status !== "interrupted") throw new Error("This task is not interrupted");
    entry.status = "queued";
    const request = entry.interruptedText || this.state.data.messages.find((message) => message.id === entry.sourceId)?.text || "";
    const sourceId = entry.interruptedSourceId || entry.sourceId;
    entry.interruptedText = undefined;
    entry.interruptedSourceId = undefined;
    const turn: Turn = { id: randomUUID(), sessionId: entry.sessionId, entryId, sourceId, text: `Continue the interrupted request in this conversation:\n${request}`, status: "queued", createdAt: now() };
    const firstWaiting = this.state.data.turns.findIndex((item) => item.sessionId === entry.sessionId);
    this.state.data.turns.splice(firstWaiting < 0 ? this.state.data.turns.length : firstWaiting, 0, turn);
    this.state.data.sessions.find((session) => session.id === entry.sessionId)!.status = "idle";
    this.state.save();
    this.drain();
  }
  transcript(sessionId: string) {
    const session = this.state.data.sessions.find((item) => item.id === sessionId);
    if (!session) throw new Error("Conversation not found");
    return { session, messages: this.pi.transcript(session.file), queue: this.state.data.turns.filter((turn) => turn.sessionId === sessionId) };
  }
  async suggestion(sessionId: string, replyId: string) {
    const current = () => {
      const record = this.state.data.sessions.find((session) => session.id === sessionId);
      if (!record) throw new Error("Conversation not found");
      if (record.status !== "idle" || this.state.data.turns.some((turn) => turn.sessionId === sessionId)) return null;
      const messages = this.pi.transcript(record.file);
      const last = messages.at(-1);
      return last?.id === replyId && last.completed ? messages : null;
    };
    const messages = current();
    if (!messages) return { text: null };
    const text = await this.pi.suggestions.get(sessionId, replyId, messages.filter((message) => message.role === "user" || message.completed));
    return { text: current() ? text : null };
  }
  private drain() {
    if (this.closing) return;
    for (const turn of this.state.data.turns) {
      if (this.active.size + this.starting.size >= this.concurrency) break;
      if (turn.status !== "queued" || this.active.has(turn.sessionId) || this.starting.has(turn.sessionId) ||
        this.state.data.sessions.find((session) => session.id === turn.sessionId)?.status === "interrupted") continue;
      this.starting.add(turn.sessionId);
      void this.run(turn);
    }
  }
  private async run(turn: Turn) {
    const record = this.state.data.sessions.find((session) => session.id === turn.sessionId)!;
    turn.status = "running";
    record.status = "running";
    const entry = this.state.data.entries.find((item) => item.id === turn.entryId);
    if (entry) entry.status = "working";
    this.state.save();
    let session: AgentSession | undefined;
    let active: Active | undefined;
    let interruptedTurn = false;
    try {
      session = await this.pi.open(record.cwd, record.file);
      active = { session, turn, output: "", error: "", stopped: false, commentary: "", tool: "", thinking: "", lastProgress: "", savedProgress: "" };
      this.active.set(record.id, active);
      this.starting.delete(record.id);
      if (this.pendingStops.has(record.id)) { active.stopped = true; throw new Error("Stopped"); }
      const progress = () => clean(active!.commentary || active!.tool || active!.thinking).trim().slice(-1200);
      const showProgress = () => {
        const text = progress();
        if (text === active!.lastProgress) return;
        active!.lastProgress = text;
        if (turn.sourceId) this.emit({ type: "homeActivity", sourceId: turn.sourceId, text });
      };
      const saveProgress = () => {
        const text = progress();
        if (!entry || !text || text === active!.savedProgress) return;
        active!.savedProgress = text;
        this.state.update(entry, text, "progress", "working", turn.sourceId);
      };
      let firstUserMessage = true;
      session.subscribe((event) => {
        if (event.type === "message_end" && event.message.role === "user" && firstUserMessage) {
          firstUserMessage = false;
          if (this.state.data.messages.find((message) => message.id === turn.sourceId)?.reaction)
            session!.sessionManager.appendCustomEntry("assistant-reaction", { reaction: "thumbs-up", replyToId: turn.replyToId });
        }
        if (event.type === "message_start" && event.message.role === "assistant") {
          active!.commentary = active!.tool = active!.thinking = "";
          showProgress();
        }
        if (event.type === "message_update") {
          const update = event.assistantMessageEvent;
          if (update.type === "thinking_start") { active!.thinking = ""; showProgress(); }
          if (update.type === "thinking_delta") { active!.thinking += update.delta; showProgress(); }
          if (update.type === "thinking_end") { active!.thinking = update.content; showProgress(); saveProgress(); }
          if (update.type === "text_delta") {
            if (!active!.tool.startsWith("Web search") && !active!.tool.startsWith("Opening:")) { active!.commentary += update.delta; showProgress(); }
            this.emit({ type: "delta", sessionId: record.id, delta: update.delta });
          }
        }
        if (event.type === "message_end" && event.message.role === "assistant") {
          const text = assistantText(event.message);
          if (text && event.message.stopReason !== "toolUse") active!.output = text;
          if (event.message.stopReason === "error") active!.error = event.message.errorMessage || "Model error";
          if (event.message.stopReason === "toolUse") { if (text) active!.commentary = text; showProgress(); saveProgress(); }
        }
        if (event.type === "tool_execution_start") {
          const label = toolLabel(event.toolName, event.args);
          this.emit({ type: "activity", sessionId: record.id, label });
          active!.tool = label;
          showProgress();
          saveProgress();
        }
      });
      const replied = turn.replyToId && this.replyTarget(turn.replyToId, record.id);
      const prompt = replyPrompt(turn.text, replied || undefined);
      this.pi.onSearchActivity(session, (label) => {
        active!.commentary = "";
        active!.tool = label;
        showProgress();
        saveProgress();
      });
      await session.prompt(prompt, { expandPromptTemplates: false });
      if (active.stopped) throw new Error("Stopped");
      if (active.error) throw new Error(active.error);
      if (!active.output) throw new Error("Agent returned no final reply");
      const replyId = [...session.sessionManager.getBranch()].reverse().find((item) => item.type === "message" && item.message.role === "assistant")?.id;
      if (entry) this.state.update(entry, clean(active.output), "result", "ready", turn.sourceId, replyId);
      if (replyId) {
        // Optional background suggestions must never turn completed work into a failed turn.
        try { void this.pi.suggestions.get(record.id, replyId,
          this.pi.transcript(record.file).filter((message) => message.role === "user" || message.completed)); }
        catch {}
      }
    } catch (error) {
      const interrupted = active?.stopped || errorText(error).toLowerCase().includes("abort");
      interruptedTurn = !!interrupted;
      if (entry) {
        if (interrupted) { entry.interruptedText = turn.text; entry.interruptedSourceId = turn.sourceId; }
        this.state.update(entry, interrupted ? "Stopped. You can continue this conversation." : errorText(error), "error", interrupted ? "interrupted" : "failed", turn.sourceId);
      }
    } finally {
      if (turn.sourceId) this.emit({ type: "homeActivity", sourceId: turn.sourceId, text: "" });
      if (session) this.pi.dispose(session);
      this.active.delete(record.id);
      this.starting.delete(record.id);
      this.pendingStops.delete(record.id);
      record.status = interruptedTurn || this.closing ? "interrupted" : "idle";
      this.state.data.turns = this.state.data.turns.filter((item) => item.id !== turn.id);
      this.state.save();
      this.drain();
    }
  }
}

